select business_date as date_, security_id, 'SP500_45' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-16' and business_date <= date '2025-06-16' and weight_ndo>0 and id_cppib_index = 'SP500_45_GR_USD_0_0' and security_id is not null

/* cppi::55e20e2d4de044f7a80dfbe14ef41540b1557896dc594dd6b42aed94bdc69c44 */
select business_date as date_, security_id, 'SP500_35' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-12' and business_date <= date '2025-06-16' and weight_ndo>0 and id_cppib_index = 'SP500_35_GR_USD_0_0' and security_id is not null

